    enonce: "<span dir=\"ltr\" class=\"expr pt\">ABE</span> مثلّث قائم الزاوية في <span dir=\"ltr\" class=\"expr pt\">E</span> بحيث <span dir=\"ltr\" class=\"expr pt\">AE = 9</span> و <span dir=\"ltr\" class=\"expr pt\">EB = 2.</span><br><svg class=\"figure\" direction=\"ltr\" viewBox=\"0 0 169 64\" width=\"169\" height=\"64\" xmlns=\"http://www.w3.org/2000/svg\"><g transform=\"translate(-40.5 -45.3)\"><line x1=\"184.2\" y1=\"92.1\" x2=\"65.8\" y2=\"92.1\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"65.8\" y1=\"92.1\" x2=\"65.8\" y2=\"65.8\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"65.8\" y1=\"65.8\" x2=\"184.2\" y2=\"92.1\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><polyline points=\"76.8,92.1 76.8,81.1 65.8,81.1\" fill=\"none\" stroke=\"#c0392b\" stroke-width=\"1.3\"/><circle cx=\"65.8\" cy=\"92.1\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"51.1\" y=\"99.4\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">E</text><circle cx=\"184.2\" cy=\"92.1\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"199.1\" y=\"97.8\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">A</text><circle cx=\"65.8\" cy=\"65.8\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"52.1\" y=\"63.7\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">B</text></g></svg><br>أحسب المسافة <span dir=\"ltr\" class=\"expr pt\">AB.</span>",
