    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">(AC) // (BJ)</span>"},{"quoi":"في المثلّث MJB لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(CA) // (JB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">C ∈ (MJ)</span>  و  <span dir=\"ltr\" class=\"expr pt\">A ∈ (MB)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">MC</span><span class=\"den\">MJ</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">MA</span><span class=\"den\">MB</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">CA</span><span class=\"den\">JB</span></span>"},{"quoi":"النتيجة","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">MC</span><span class=\"den\">MJ</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">MA</span><span class=\"den\">MB</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">CA</span><span class=\"den\">JB</span></span>"}],
