    enonce: "النّقط <span dir=\"ltr\" class=\"expr pt\">O</span> و <span dir=\"ltr\" class=\"expr pt\">A</span> و <span dir=\"ltr\" class=\"expr pt\">B</span> و <span dir=\"ltr\" class=\"expr pt\">C</span> على استقامة واحدة، و <span dir=\"ltr\" class=\"expr pt\">D</span> نقطة من <span dir=\"ltr\" class=\"expr pt\">[OE].</span><br><span dir=\"ltr\" class=\"expr pt\">(AD) // (BE)</span> و <span dir=\"ltr\" class=\"expr pt\">(DB) // (EC).</span><br><span dir=\"ltr\" class=\"expr pt\">OA = 3</span> و <span dir=\"ltr\" class=\"expr pt\">AB = 2</span> و <span dir=\"ltr\" class=\"expr pt\">OE = 50.</span><br><svg class=\"figure\" direction=\"ltr\" viewBox=\"0 0 77 216\" width=\"77\" height=\"216\" xmlns=\"http://www.w3.org/2000/svg\"><g transform=\"translate(1.1 12.7)\"><line x1=\"16.4\" y1=\"173.6\" x2=\"43.7\" y2=\"173.6\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"16.4\" y1=\"173.6\" x2=\"62.2\" y2=\"16.4\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"26.2\" y1=\"173.6\" x2=\"43.9\" y2=\"79.3\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"32.8\" y1=\"173.6\" x2=\"62.2\" y2=\"16.4\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"43.9\" y1=\"79.3\" x2=\"32.8\" y2=\"173.6\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"62.2\" y1=\"16.4\" x2=\"43.7\" y2=\"173.6\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><circle cx=\"16.4\" cy=\"173.6\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"9.6\" y=\"191.0\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">O</text><circle cx=\"26.2\" cy=\"173.6\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"22.3\" y=\"192.1\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">A</text><circle cx=\"32.8\" cy=\"173.6\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"31.1\" y=\"192.5\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">B</text><circle cx=\"43.7\" cy=\"173.6\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"45.9\" y=\"192.5\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">C</text><circle cx=\"43.9\" cy=\"79.3\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"45.7\" y=\"68.4\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">D</text><circle cx=\"62.2\" cy=\"16.4\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"65.4\" y=\"5.7\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">E</text></g></svg><br><span dir=\"ltr\" class=\"expr\">1)</span> أحسب <span dir=\"ltr\" class=\"expr pt\">OB.</span><br><span dir=\"ltr\" class=\"expr\">2)</span> أحسب النّسبة <span dir=\"ltr\" class=\"expr pt\">OD/OE.</span><br><span dir=\"ltr\" class=\"expr\">3)</span> استنتج <span dir=\"ltr\" class=\"expr pt\">OD.</span><br><span dir=\"ltr\" class=\"expr\">4)</span> بيّن أنّ <span dir=\"ltr\" class=\"expr pt\">OB/OC = OD/OE.</span>",
    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">AO = 3</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB = 2</span>  و  <span dir=\"ltr\" class=\"expr pt\">EO = 50</span>  و  <span dir=\"ltr\" class=\"expr pt\">(AD) // (BE)</span>  و  <span dir=\"ltr\" class=\"expr pt\">(BD) // (CE)</span>"},{"quoi":"1)","math":"أحسب <span dir=\"ltr\" class=\"expr pt\">OB.</span>"},{"quoi":"القاعدة","math":"إذا كانت النقطة <span dir=\"ltr\" class=\"expr pt\">B</span> بين <span dir=\"ltr\" class=\"expr pt\">A</span> و <span dir=\"ltr\" class=\"expr pt\">C</span> فإنّ <span dir=\"ltr\" class=\"expr pt\">AC = AB + BC</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">AO = 3</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB = 2</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">BO = 5</span>  ، لأنّ <span dir=\"ltr\" class=\"expr pt\">BO = 3 + 2</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">BO = 5</span>"},{"quoi":"2)","math":"أحسب النّسبة <span dir=\"ltr\" class=\"expr pt\">OD/OE.</span>"},{"quoi":"القاعدة","math":"بتطبيق نظرية طالس على كلّ متوازيين، نحصل على العلاقة بين النّسب"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">(AD) // (BE)</span>  و  <span dir=\"ltr\" class=\"expr pt\">AO = 3</span>  و  <span dir=\"ltr\" class=\"expr pt\">BO = 5</span>  إذن  <span class=\"frac\" dir=\"ltr\"><span class=\"num\">OD</span><span class=\"den\">OE</span></span> <span dir=\"ltr\" class=\"expr\">=</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">3</span><span class=\"den\">5</span></span>"},{"quoi":"النتيجة","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">OD</span><span class=\"den\">OE</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">3</span><span class=\"den\">5</span></span>"},{"quoi":"3)","math":"استنتج <span dir=\"ltr\" class=\"expr pt\">OD.</span>"},{"quoi":"في المثلّث OBE لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(AD) // (BE)</span>  و  <span dir=\"ltr\" class=\"expr pt\">A ∈ (OB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">D ∈ (OE)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">OA</span><span class=\"den\">OB</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">OD</span><span class=\"den\">OE</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AD</span><span class=\"den\">BE</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">3</span><span class=\"den\">5</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">DO</span><span class=\"den\">50</span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">DO = 30</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">DO = 30</span>"},{"quoi":"4)","math":"بيّن أنّ <span dir=\"ltr\" class=\"expr pt\">OB/OC = OD/OE.</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">(BD) // (CE)</span>  و  <span dir=\"ltr\" class=\"expr pt\">DO = 30</span>  و  <span dir=\"ltr\" class=\"expr pt\">EO = 50</span>  إذن  <span class=\"frac\" dir=\"ltr\"><span class=\"num\">OB</span><span class=\"den\">OC</span></span> <span dir=\"ltr\" class=\"expr\">=</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">3</span><span class=\"den\">5</span></span>"},{"quoi":"النتيجة","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">OB</span><span class=\"den\">OC</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">3</span><span class=\"den\">5</span></span>"}],
    indice: "طالس في المثلّث OBE يعطي OD/OE = OA/OB",
